import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.F7eQ-ohH.js";const s="/bzygq/assets/b1d2adc8be5f4611859aa8a1fcad14d1.CkzLKXXw.png",n="/bzygq/assets/866ab9e40fa840e2875d10ce962a81f5.BumsqVpX.png",i="/bzygq/assets/e4ac22783d324915b3d11f22b5e2e1db.iTPuXgtl.png",l="/bzygq/assets/2687603997334f47baa4ccd786a45213.kJkWeCq8.png",p="/bzygq/assets/1f154a2c818c4dd6b6f92fead8aeb5f9.C8N4hDRI.png",f=JSON.parse('{"title":"二、CPU多级缓存架构","description":"","frontmatter":{},"headers":[],"relativePath":"Java面试问题汇总/Java虚拟机/二、CPU多级缓存架构.md","filePath":"Java面试问题汇总/Java虚拟机/二、CPU多级缓存架构.md","lastUpdated":1788929995000}'),c={name:"Java面试问题汇总/Java虚拟机/二、CPU多级缓存架构.md"};function h(g,a,d,C,b,P){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="二、cpu多级缓存架构" tabindex="-1">二、CPU多级缓存架构 <a class="header-anchor" href="#二、cpu多级缓存架构" aria-label="Permalink to &quot;二、CPU多级缓存架构&quot;">​</a></h1><h2 id="为什么要了解缓存架构" tabindex="-1">为什么要了解缓存架构？ <a class="header-anchor" href="#为什么要了解缓存架构" aria-label="Permalink to &quot;为什么要了解缓存架构？&quot;">​</a></h2><p>在实际工作中或者面试过程中，多线程是很多同学绕不开的一个话题，即使是在央企国企的技术岗，多线程也是属于必问的问题。</p><p>但是，从顶层或者业务层去理解为什么要同步、异步、多线程操作、并发问题和锁这些概念会非常复杂，如果我们换一条思路直击问题根本，多线程问题的实质其实就是由于三级缓存架构造成的数据一致性问题。</p><p>所以了解CPU的缓存架构，对于了解Java多线程和JVM相关的一些东西是非常有帮助的。</p><h3 id="cpu多级缓存架构概述" tabindex="-1">CPU多级缓存架构概述 <a class="header-anchor" href="#cpu多级缓存架构概述" aria-label="Permalink to &quot;CPU多级缓存架构概述&quot;">​</a></h3><p>CPU的执行效率是内存读取效率的10倍左右，而内存的读取效率又是磁盘读取效率的几千倍到几百万倍，也就是说在执行效率上CPU &gt;&gt; 内存 &gt;&gt; 硬盘。因此，为了提升CPU的执行效率，尽量减少CPU与内存之间的交互以提升系统的运行效率，CPU上集成了多级缓存架构，一般是3级缓存架构。</p><p>对于3级缓存架构而言，CPU从内存当中读取数据的时候，并不会只读取自己想要的部分，而是会读取足够的字节来填入高速缓存行（Cache Line），不同的CPU的高速缓存行的大小不同。这样一来当CPU需要访问相邻数据的时候，就不必每次都从内存中读取，提升了CPU的执行效率。</p><p><img src="'+s+'" alt="images/M5MzbEZZToxBrex6t5JcA4rHnZb.png"></p><p>images/M5MzbEZZToxBrex6t5JcA4rHnZb.png</p><p>如上图所示，现在的CPU一般是多核心结构，即存在多个内核可以执行程序。因此，计算机的前面2级缓存L1、L2缓存被设计为处于CPU每个核心的内部供单个核心使用，而L3缓存则是设置在CPU当中，供CPU内部的所有的核心使用。</p><p>具体来说，L1 Cache（一级缓存）通常被分为数据缓存和指令缓存，即L1 D-Cache、L1 I-Cache，而L2 Cache（二级缓存）和L3 Cache（三级缓存）则只是缓存数据。</p><p>L1 Cache（一级缓存）通常被分为<strong>数据缓存</strong>和<strong>指令缓存</strong>，即L1 D-Cache、L1 I-Cache，每个逻辑核都有自己独立的L1 Cache。数据缓存，用于存储最近被访问的数据，提供对数据的快速读取和写入。指令缓存， 用于存储处理器当前正在执行的指令，以提高指令的获取速度。</p><p>L2 Cache（二级缓存）比一级缓存大一些，一般大小在几百k的级别，如256k。 一般情况下，每个物理核拥有自己独立的L2 Cache，但逻辑核可能共享同一物理核的L2 Cache。 L2 Cache的容量比L1 Cache大，访问速度相对较快，但比L1 Cache慢。二级缓存就是一级缓存的缓冲期，一级缓存的制造成本高容量有限，二级缓存的作用就是存储那些CPU处理时需要用到，但是一级缓存又无法存储的数据。</p><p>L3 Cache（三级缓存）比二级缓存更大，一般大小在10几MB，如12MB。L3 Cache通常位于多个物理核之间，被它们共享， L3 Cache的容量相对较大，速度比L2 Cache慢一些。</p><p>从缓存的存储空间来说从大到小依次为：内存 &gt; L3 Cache &gt; L2 Cache &gt; L1 Cache &gt; 寄存器。从缓存的存取速度上来说，从快到慢依次为：寄存器 &gt; L1 Cache &gt; L2 Cache &gt; L3 Cache &gt; 内存，如下文所示：</p><p>这种层次结构有助于提高系统性能，因为它充分利用了局部性原理，并在速度和容量之间找到了平衡。较小但更接近CPU的缓存层次可以迅速提供处理器所需的数据，而较大但速度相对较慢的层次则提供了更大的存储容量。</p><h3 id="缓存原理" tabindex="-1">缓存原理 <a class="header-anchor" href="#缓存原理" aria-label="Permalink to &quot;缓存原理&quot;">​</a></h3><h4 id="缓存行-cache-line" tabindex="-1">缓存行（Cache Line） <a class="header-anchor" href="#缓存行-cache-line" aria-label="Permalink to &quot;缓存行（Cache Line）&quot;">​</a></h4><p><img src="'+n+'" alt="images/PWn0bfJdfoLJXrxpJEscQsoNnne.png"></p><p>images/PWn0bfJdfoLJXrxpJEscQsoNnne.png</p><p>Cache Line是缓存对数据进行存取的最小单元，根据局部性原理缓存每次读取数据的时候不会只读取单个数据，而是会读取相邻的一行数据，以提升数据的存取效率。每个Cache Line包含Flag、Tag和Data三个部分，Data的大小一般是64 Bytes，而Flag和Tag则与CPU型号相关。从内存向缓存读写数据的时候都是加载整个Cache Line，并且一个Cache Line和一块儿大小相同的内存区域相关联。</p><p>如上图所示，缓存是按照矩阵方式排列(M × N)，横向是<strong>组(Set)</strong>，纵向是<strong>路(Way)</strong>。每一个元素是缓存行(cache line)。那么给定一个虚拟地址 <strong>addr</strong> 如何在缓存中定位它呢？首先把它所在的<strong>组号</strong>找到，即：</p><p>//左移6位是因为 Block Offset 占 addr 的低 6 位，Data 为 64 字节 Set Index = (addr &gt;&gt; 6) % M;</p><p>然后遍历该组所有的路，找到 <strong>cache line</strong> 中的 <strong>Tag</strong> 与 <strong>addr</strong> 中 <strong>Tag</strong> 相等为止，所有路都没有匹配成功，那么缓存未命中。</p><p>整个缓存容量 = Set × Way × 缓存行大小</p><h4 id="缓存行替换策略" tabindex="-1">缓存行替换策略 <a class="header-anchor" href="#缓存行替换策略" aria-label="Permalink to &quot;缓存行替换策略&quot;">​</a></h4><p><img src="'+i+'" alt="images/VoQJb58pgosg1ox0SslcQjp8nUe.png"></p><p>images/VoQJb58pgosg1ox0SslcQjp8nUe.png</p><p>常用的缓存替换策略是<strong>最近最少使用算法</strong>（Least Recently Used，<strong>LRU</strong>），可以给每个缓存行设置一个参数记录其访问次数，每次需要淘汰缓存行的时候使用频率最低的缓存行被淘汰。</p><p>LRU算法的实现方式很多，最常用的是——**位矩阵。**位矩阵会定义一个行、列都与缓存路数（way）相同的矩阵，当访问某个way对应的缓存行的时候，会将该路对应的所有行置为1，再将该way对应的所有列都置为0。那么，最近最少使用的缓存行所对应的矩阵行当中的个数最少，就会最先被替换出去。</p><h5 id="缓存缺失" tabindex="-1">缓存缺失 <a class="header-anchor" href="#缓存缺失" aria-label="Permalink to &quot;缓存缺失&quot;">​</a></h5><p>缓存缺失就是缓存未命中，需要把内存中数据加载到缓存，所以运行速度会变慢。</p><h5 id="程序局部性" tabindex="-1"><strong>程序局部性</strong> <a class="header-anchor" href="#程序局部性" aria-label="Permalink to &quot;**程序局部性**&quot;">​</a></h5><p>程序局部性就是读写内存数据时读写连续的内存空间，目的是让缓存可以命中，减少缓存缺失导致替换的开销。</p><p>我电脑上运行下面代码</p><p>int M = 10000, N = 10000; char ( *a)[N] = (char(* )[N])calloc(M * N, sizeof(char)); for(int i = 0; i &lt; M; i++) for(int j = 0; j &lt; N; j++) a[i][j]++;</p><p>结果：循环 100000000 次，耗时 314 ms。利用了程序局部性原理，缓存命中率高。</p><p>修改上面的代码如下，并运行</p><p>int M = 10000, N = 10000; char (*a)[N] = (char(*)[N])calloc(M * N, sizeof(char)); for(int j = 0; j &lt; N; j++) for(int i = 0; i &lt; M; i++) a[i][j]++;</p><p>结果：循环 100000000 次，耗时 1187 ms。没有利用程序局部性原理，缓存命中率低，所以耗时增加了 2 倍。</p><h5 id="伪共享-false-sharing" tabindex="-1"><strong>伪共享（false-sharing）</strong> <a class="header-anchor" href="#伪共享-false-sharing" aria-label="Permalink to &quot;**伪共享（false-sharing）**&quot;">​</a></h5><p>当两个线程同时各自修改两个相邻的变量，由于缓存是<strong>按缓存行来整体组织</strong>的，当一个线程对缓存行中数据执行写操作时，必须通知其他线程该缓存行失效，导致另一个线程从缓存中读取其想修改的数据失败，必须从内存重新加载，导致性能下降。</p><p>我电脑运行下面代码</p><p>struct S { long long a; long long b; } s; std::thread t1( &amp; { for(int i = 0; i &lt; 100000000; i++) s.a++; }); std::thread t2( &amp; { for(int i = 0; i &lt; 100000000; i++) s.b++; });</p><p>结果：耗时 512 ms，原因上面提到了，就是两个线程互相影响，使对方的缓存行失效，导致直接从内存读取数据。</p><p>解决办法是对上面代码做如下修改：</p><p>struct S { long long a; long long noop[8]; long long b; } s;</p><p>结果：耗时 181 ms，原因是通过 long long noop[8] 把两个数据（a 和 b）划分到两个不同的缓存行中，不再互相使对方的缓存失效，所以速度变快了。</p><h4 id="寄存器和缓存区别" tabindex="-1">寄存器和缓存区别 <a class="header-anchor" href="#寄存器和缓存区别" aria-label="Permalink to &quot;寄存器和缓存区别&quot;">​</a></h4><h5 id="理论上的区别" tabindex="-1">理论上的区别 <a class="header-anchor" href="#理论上的区别" aria-label="Permalink to &quot;理论上的区别&quot;">​</a></h5><p>寄存器（Registers）和缓存（Cache）是计算机体系结构中的两种不同的硬件结构，它们在功能和作用上有所区别。寄存器是位于CPU（中央处理器）内部的高速存储器，用于存储指令执行过程中的数据和中间结果。直接与CPU内部的执行单元相连，因此它们的访问速度非常快，可以在一个时钟周期内读取或写入数据。寄存器的容量有限，而且每个CPU架构都有特定的寄存器数量和功能。寄存器用于暂存指令的操作数、中间计算结果和程序计数器等。</p><p>缓存是位于CPU和主内存（RAM）之间的高速存储器，用于缓存常用的数据和指令，以提高数据访问的效率。缓存的容量通常比寄存器大，但仍然远远小于主内存的容量。缓存被分为多个级别（如L1、L2、L3缓存），每个级别的容量和访问速度逐渐降低。缓存的访问速度比主内存快得多，但比寄存器慢一些。缓存采用一定的替换策略和缓存块的管理机制，以提供高效的数据访问。区别总结如下：</p><ol><li>速度：寄存器是最快的存储器，可以在一个时钟周期内访问；缓存的访问速度比主内存快，但比寄存器慢一些。</li><li>容量：寄存器容量有限，每个CPU架构都有特定的寄存器数量和功能；缓存的容量比寄存器大，但仍然远远小于主内存的容量。</li><li>位置：寄存器位于CPU内部，直接与执行单元相连；缓存位于CPU和主内存之间。</li><li>功能：寄存器用于存储指令执行过程中的数据和中间结果；缓存用于缓存常用的数据和指令，以提高数据访问效率。 总体而言，寄存器和缓存在计算机体系结构中扮演不同的角色。寄存器用于快速存取和处理数据，而缓存则用于提供更快的数据访问速度，减少CPU对主内存的访问次数，提高计算机系统的整体性能。</li></ol><h5 id="逻辑电路上区别" tabindex="-1">逻辑电路上区别 <a class="header-anchor" href="#逻辑电路上区别" aria-label="Permalink to &quot;逻辑电路上区别&quot;">​</a></h5><ol><li><strong>寄存器逻辑电路结构：</strong></li></ol><p><img src="'+l+'" alt="images/Ph8Gb1Mk5o0BQpxjR6AcZwHZnVe.png"></p><p>images/Ph8Gb1Mk5o0BQpxjR6AcZwHZnVe.png</p><ul><li>寄存器是存储器件，通常由触发器（flip-flop）构成，每个触发器可以存储一个位或多个位的数据。</li><li>寄存器的逻辑电路结构相对简单，主要包括数据输入端、数据输出端、时钟信号和控制信号。</li><li>寄存器的主要功能是存储和暂存数据，它们在CPU内部用于保存指令执行过程中的数据和中间结果。</li></ul><ol><li><strong>缓存逻辑电路结构：</strong></li></ol><ul><li>缓存是高速缓存存储器，通常由多级缓存组成。每个级别的缓存都有自己的逻辑电路结构。</li><li>缓存的逻辑电路结构更加复杂，包括标签（Tag）、索引（Index）、块（Block）和数据存储器等组成部分。</li><li>缓存的逻辑电路结构还涉及到替换策略、缓存一致性协议和高速缓存的映射方式（如直接映射、全相联映射和组相联映射）等。</li><li>缓存的主要功能是通过在CPU和主内存之间提供快速的数据访问，减少对主内存的访问次数，提高数据访问效率。 总结起来，寄存器的逻辑电路结构相对简单，主要由触发器构成，用于存储和暂存数据。而缓存的逻辑电路结构更加复杂，包括标签、索引、块和数据存储器等组成部分，用于提供快速的数据访问和有效的缓存策略。</li></ul><h4 id="总线和总线锁" tabindex="-1">总线和总线锁 <a class="header-anchor" href="#总线和总线锁" aria-label="Permalink to &quot;总线和总线锁&quot;">​</a></h4><p><img src="'+p+'" alt="images/M7yRbzkKoo6M7fxiwVFcrfa7nrc.png"></p><p>images/M7yRbzkKoo6M7fxiwVFcrfa7nrc.png</p><h5 id="总线-bus" tabindex="-1">总线（Bus） <a class="header-anchor" href="#总线-bus" aria-label="Permalink to &quot;总线（Bus）&quot;">​</a></h5><p>从它的英文名字可以看出，就像个巴士一样，用来运输计算机各个硬件设备之间的数据。 实际上总线是计算机内部用于传输数据、地址和控制信号的硬件设备，连接了计算机内部的各个部件，如中央处理（CPU）、内存、输入输出设备等。总线主要分为数据总线、地址总线和控制总线几类：</p><ol><li><strong>数据总线（Data Bus）：</strong> 用于传输数据信号，指示数据在各个组件之间的传送方向。例如，32位数据总线可以一次传输32位的数据。</li><li><strong>地址总线（Address Bus）：</strong> 用于传输内存地址或I/O（输入/输出）设备的物理地址，地址总线的宽度决定了计算机的寻址能力，即能够寻址的内存或设备的数量。</li><li><strong>控制总线（Control Bus）：</strong> 用于传输控制信号，指导和同步计算机内部各个部件的操作，控制总线传输的信号包括读、写、中断、时钟等。</li></ol><h5 id="总线锁-bus-lock" tabindex="-1"><strong>总线锁（Bus Lock）</strong> <a class="header-anchor" href="#总线锁-bus-lock" aria-label="Permalink to &quot;**总线锁（Bus Lock）**&quot;">​</a></h5><p>总线锁是一种处理器级别的锁机制，用于实现多处理器系统中的原子操作或互斥访问共享资源（如内存，L3缓存）。</p><p>在多处理器系统中，多个处理器共享同一条系统总线（Bus）。当多个处理器需要同时访问共享资源或进行原子操作时，为了保证操作的原子性和正确性，需要使用总线锁来进行同步。</p><p>总线锁的原理是通过在总线上发送锁信号来实现互斥访问。当一个处理器需要访问共享资源时，它会首先发送一个请求总线锁的信号，如果锁是可用的（没有其他处理器正在使用），那么该处理器获得总线锁，可以执行相应的操作。其他处理器在收到总线锁请求信号后，会等待锁释放。一旦处理器完成了对共享资源的访问，它会释放总线锁，允许其他处理器获取锁并执行相应的操作。</p><p>总线锁的优点是实现简单，适用于小规模的多处理器系统。然而，总线锁也存在一些缺点。首先，当多个处理器竞争总线锁时，会导致处理器之间的争用，降低系统的并行度。此外，总线锁是对整个总线进行加锁，可能导致其他处理器的访问被阻塞，从而影响整个系统的性能。</p><p>随着计算机体系结构的发展，现代处理器通常采用更高级的锁机制，如缓存行锁（Cache Line Locking）或基于硬件的原子操作指令（如CAS指令），以提供更细粒度的锁定和更好的性能。这些机制通常在缓存层或处理器内部进行锁定，减少了对总线的竞争，提高了并发性能。因此，总线锁在现代处理器中的应用已经相对较少。</p>',73)])])}const m=e(c,[["render",h]]);export{f as __pageData,m as default};
